build(a, snap) {
    const B = a.board.map((r) => r.split("")), word = a.word, m = B.length, n = B[0].length, path = [];
    const view = (cur, done) => [
      { t: "grid", label: "board", rows: B.map((r, i) => r.map((v, j) => { const on = path.some(([x, y]) => x === i && y === j); return { v, cls: done && on ? "c" : cur && cur[0] === i && cur[1] === j ? "a" : on ? "e" : "" }; })) },
      { t: "array", label: "word", items: word.split("").map((ch, k) => ({ v: ch, cls: k < path.length ? (done ? "c" : "e") : "" })), ptrs: { k: path.length < word.length ? path.length : null } },
    ];
    snap("开始", `在网格里找单词 <b>${word}</b>。每个格子都当一次起点，相邻是指上下左右。`, view(null));
    const dfs = (i, j, k) => {
      path.push([i, j]);
      if (k === word.length - 1) return true;
      snap("匹配", `(${i},${j}) 是 ${word[k]}，对上了 word[${k}]。占住它，去相邻格子找 <b>${word[k + 1]}</b>。`, view([i, j]), { facts: [["已匹配", `${k + 1} / ${word.length}`]] });
      for (const [x, y] of [[i + 1, j], [i - 1, j], [i, j + 1], [i, j - 1]]) {
        if (x < 0 || y < 0 || x >= m || y >= n || path.some(([p, q]) => p === x && q === y) || B[x][y] !== word[k + 1]) continue;
        if (dfs(x, y, k + 1)) return true;
      }
      path.pop();
      snap("回退", `(${i},${j}) 周围没有能接上的 ${word[k + 1]}，这条路走不通。去掉它的标记，退回上一步。`, view(path.length ? path[path.length - 1] : null), { kind: "warn", facts: [["已匹配", `${k} / ${word.length}`]] });
      return false;
    };
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
      if (B[i][j] !== word[0]) continue;
      snap("起点", `(${i},${j}) 是 ${word[0]}，从这里出发试试。`, view([i, j]));
      if (dfs(i, j, 0)) { snap("找到", `最后一个字母也对上了，路径是 ${path.map(([x, y]) => `(${x},${y})`).join(" → ")}。返回 <b>true</b>。`, view(null, true), { kind: "ok", ans: true, facts: [["已匹配", `${word.length} / ${word.length}`]] }); return; }
    }
    snap("找不到", `所有起点都试过了，拼不出 ${word}，返回 <b>false</b>。`, view(null), { kind: "warn", ans: false });
  }

